package app.yoru.android;
import android.app.job.*;import android.content.*;import android.webkit.CookieManager;import android.app.NotificationManager;import org.json.JSONObject;import java.net.*;import java.nio.charset.StandardCharsets;import java.io.*;
// Retry token rotation even when no Activity/WebView page is currently open.
public class PushRegistrationService extends JobService {
 private Thread worker;
 public static void schedule(Context context){if(BuildConfig.FIREBASE_APP_ID.isEmpty())return;JobInfo info=new JobInfo.Builder(8301,new ComponentName(context,PushRegistrationService.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setBackoffCriteria(30000,JobInfo.BACKOFF_POLICY_EXPONENTIAL).build();context.getSystemService(JobScheduler.class).schedule(info);}
 @Override public boolean onStartJob(JobParameters params){worker=new Thread(()->{boolean done;try{done=register();}catch(Exception error){done=false;}jobFinished(params,!done);},"yoru-token-register");worker.start();return true;}
 @Override public boolean onStopJob(JobParameters params){if(worker!=null)worker.interrupt();return true;}
 private boolean register() throws Exception {android.content.SharedPreferences prefs=getSharedPreferences("yoru",MODE_PRIVATE);String account=prefs.getString("account",""),token=prefs.getString("token",""),id=prefs.getString("installation",""),secret=prefs.getString("secret","");if(account.isEmpty()||token.isEmpty()||id.isEmpty()||secret.isEmpty())return true;String cookies=CookieManager.getInstance().getCookie(BuildConfig.SITE_ORIGIN);if(cookies==null)return true;
 HttpURLConnection session=request("/api/mobile/session",cookies);int status=session.getResponseCode();if(status>=500)return false;if(status!=200)return true;for(java.util.Map.Entry<String,java.util.List<String>> header:session.getHeaderFields().entrySet())if(header.getKey()!=null&&header.getKey().equalsIgnoreCase("Set-Cookie"))for(String cookie:header.getValue())CookieManager.getInstance().setCookie(BuildConfig.SITE_ORIGIN,cookie);CookieManager.getInstance().flush();cookies=CookieManager.getInstance().getCookie(BuildConfig.SITE_ORIGIN);JSONObject data;try(InputStream input=session.getInputStream()){data=new JSONObject(readUtf8(input));}finally{session.disconnect();}
 if(!data.optBoolean("authenticated")||!account.equals(data.optString("userId"))){if(account.equals(prefs.getString("account",""))){prefs.edit().putString("account","").apply();getSystemService(NotificationManager.class).cancelAll();}return true;}
 if(!account.equals(prefs.getString("account","")))return true;
 HttpURLConnection connection=request("/api/mobile/push/register",cookies);connection.setRequestMethod("POST");connection.setRequestProperty("Content-Type","application/json");connection.setRequestProperty("x-csrf-token",data.getString("csrf"));connection.setDoOutput(true);byte[] body=new JSONObject().put("id",id).put("secret",secret).put("token",token).toString().getBytes(StandardCharsets.UTF_8);connection.setFixedLengthStreamingMode(body.length);try(OutputStream output=connection.getOutputStream()){output.write(body);}int result=connection.getResponseCode();connection.disconnect();return result==200||(result>=400&&result<500&&result!=403&&result!=429);
 }
 private String readUtf8(InputStream input) throws IOException {ByteArrayOutputStream output=new ByteArrayOutputStream();byte[] bytes=new byte[4096];int count;while((count=input.read(bytes))!=-1){output.write(bytes,0,count);if(output.size()>65536)throw new IOException("Response too large");}return output.toString("UTF-8");}
 private HttpURLConnection request(String path,String cookies) throws Exception {HttpURLConnection connection=(HttpURLConnection)new URL(BuildConfig.SITE_ORIGIN+path).openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(8000);connection.setReadTimeout(8000);connection.setRequestProperty("Cookie",cookies);connection.setRequestProperty("Accept","application/json");return connection;}
}
